import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('el-engano-iii', 'B',
 [dict(t=1151, e=1190, titulo='Usted no tiene comprada la vida', txt='Usted no tiene comprada la vida; se la compró Cristo, y él decide si usted se queda o se va, o usted tiene la oportunidad de alargar o acortar su vida. Mire qué tremendo. Pero yo lo bendigo a usted para que alargue su vida, para que le dé tiempo de ponerse a cuentas, que le dé tiempo para poder llegar a donde quiere el Señor, en el nombre de Jesús. Amén.'),
  dict(t=1322, e=1352, titulo='El dinero no es malo', txt='Hay gente, hermano, que empezó bien y, después de que ya hace una fortuna, se olvidan de Dios. ¿Por qué? Porque los atacó […] el dios del dinero. El dinero no es malo. Diga conmigo: el dinero no es malo. Si quieren, me prestan; no hay ningún problema. El dinero, dice, en la billetera es bueno; en el corazón es malo.'),
  dict(t=1925, e=1965, titulo='Voltee la página', txt='Así que sigamos adelante. No voltee atrás. Ya su pasado ya no lo puede arreglar. «Ay, es que cometí tantos errores por esas decisiones tan desventuradas que tomé». Ya las tomó. Voltee la página. Dios va a escribir una nueva historia en usted, una nueva serie que ni Netflix la tiene, y usted va a ser bendecido en el nombre de Jesús. Amén.')],
 [dict(t=4087, txt='Viene la palabra metanoia, que quiere decir cambiar mi manera de pensar, cambiar mi manera de actuar, cambiar mi manera de caminar.'),
  dict(t=4166, txt='Hay gente que comete el pecado y se arrepiente, pero hay gente que practica el pecado.'),
  dict(t=4793, txt='Dios conoce tu corazón mejor que tu papá, que tu mamá, que el pastor. Dios sí conoce tu corazón.')],
 ['¿Qué preocupaciones del mundo, o qué idea de las riquezas, te están ahogando hoy la Palabra? ¿Qué harías para que el dinero esté en la billetera y no en el corazón?',
  '¿Qué parte de tu pasado sigues mirando hacia atrás? ¿Qué significaría «voltear la página» esta semana?',
  'Arrepentirse es cambiar la manera de pensar, de actuar y de caminar: ¿en cuál de las tres necesitas dar un paso concreto?'])
